<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import {queryField} from './query-state'
import {Search,Plus,BookOpen,Compass,Grid2X2,List,MoreHorizontal,Archive,RotateCcw} from 'lucide-vue-next'
import {api,allPages} from '../api'
import {worldApi} from '../world/api'
import {useApp} from '../stores/app'
import {storyPath} from '../api/stories'
import {useRequestScope} from '../platform/request-scope'
import type {Book} from '../api/types'
import type {WorldInfo} from '../world/types'
import Sheet from '../components/Sheet.vue'
import PublicCatalog from '../authoring/PublicCatalog.vue'
import PageHeader from './PageHeader.vue'
import {collectionItems,filterCollection,type CollectionItem} from './collections'
import CuratedCover from '../catalog/CuratedCover.vue'
import {useCuratedArtwork} from '../catalog/curated-artwork'
const {worlds:artworkWorlds}=useCuratedArtwork()
const route=useRoute(),store=useApp(),capture=useRequestScope(),books=ref<Book[]>([]),worlds=ref<WorldInfo[]>([]),search=queryField('q'),kind=queryField('kind'),archiveQuery=queryField('archived'),archived=computed({get:()=>archiveQuery.value==='1',set:(v:boolean)=>archiveQuery.value=v?'1':''}),layout=queryField('layout','grid'),loading=ref(true),error=ref(''),busy=ref(false),selected=ref<CollectionItem>(),name=ref(''),sort=queryField('sort','recent'),favorites=ref(route.query.favorites==='1')
const mode=computed(()=>route.path==='/recent'?'recent':favorites.value?'bookmarks':'mine')
const title=computed(()=>({recent:'最近体验',bookmarks:'收藏作品',mine:'我的作品',all:'我的作品'})[mode.value])
const visible=computed(()=>filterCollection(collectionItems(books.value,worlds.value),{search:search.value,kind:kind.value,mode:mode.value,archived:archived.value,sort:sort.value}))
let epoch=0
async function load(){const scope=capture(),version=++epoch;loading.value=true;error.value='';try{const results=await Promise.allSettled([allPages<Book>('/books?status='+ (archived.value?'archived':'active')).then(items=>({items})),store.worldEnabled?worldApi<{items:WorldInfo[]}>('/worlds',{cache:true}):Promise.resolve({items:[] as WorldInfo[]})]);if(!scope.valid()||version!==epoch)return;const [b,w]=results;if(b.status==='fulfilled')books.value=b.value.items;else error.value='小说加载失败：'+String(b.reason.message||b.reason);if(w.status==='fulfilled')worlds.value=w.value.items;else error.value+=(error.value?'；':'')+'世界加载失败：'+String(w.reason.message||w.reason)}finally{if(scope.valid()&&version===epoch)loading.value=false}}
function manage(item:CollectionItem){selected.value=item;name.value=item.title;error.value=''}
async function save(status?:string){const target=selected.value;if(!target||busy.value)return;const scope=capture();busy.value=true;error.value='';try{const body={expectedVersion:target.version,...(status?{status}:target.kind==='world'?{name:name.value.trim()}:{title:name.value.trim()})};if(target.kind==='world')await worldApi('/worlds/'+target.id,{method:'PATCH',body});else await api('/books/'+target.id,{method:'PATCH',body});if(scope.valid()){selected.value=undefined;await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
watch(()=>route.query.favorites,value=>{favorites.value=value==='1'});watch(archived,load);watch(()=>route.path,()=>{epoch++;selected.value=undefined;favorites.value=route.query.favorites==='1';void load()})
onMounted(load)
</script>
<template><div class="workspace-page"><PageHeader :title="title" eyebrow="故事与阅读" :description="mode==='recent'?'继续上次的世界线，或回到已保存的阅读位置。':mode==='bookmarks'?'收藏的小说集中在这里；打开阅读器可查看章节书签。':'世界、小说和归档内容都在这里，只有你自己能看到。'"><RouterLink class="world-primary-link" to="/worlds/scripts"><Plus :size="18"/>创作作品</RouterLink><RouterLink to="/library" class="inline-link">导入小说</RouterLink></PageHeader><div class="workspace-toolbar"><label class="workspace-search"><Search :size="18"/><input v-model="search" type="search" aria-label="搜索我的作品" placeholder="搜索作品、人物或来源"></label><label>排序<select v-model="sort" aria-label="作品排序"><option value="recent">最近更新</option><option value="title">名称顺序</option></select></label><div class="workspace-view-toggle" aria-label="显示方式"><button :aria-pressed="layout==='grid'" aria-label="卡片视图" @click="layout='grid'"><Grid2X2 :size="18"/></button><button :aria-pressed="layout==='list'" aria-label="列表视图" @click="layout='list'"><List :size="18"/></button></div></div><div class="workspace-collection-filters"><nav class="workspace-pills" aria-label="作品类型"><button :aria-pressed="!kind" @click="kind=''">全部</button><button :aria-pressed="kind==='world'" @click="kind='world'">互动世界</button><button :aria-pressed="kind==='book'" @click="kind='book'">小说</button><button v-if="route.path!=='/recent'" :aria-pressed="favorites" @click="favorites=!favorites">收藏</button></nav><button v-if="mode==='mine'" :aria-pressed="archived" @click="archived=!archived"><Archive :size="16"/>{{archived?'返回作品':'归档作品'}}</button></div><p v-if="error" role="alert" class="error">{{error}} <button @click="load">重新加载</button></p><p v-if="loading" role="status" class="workspace-loading">正在打开作品库…</p><section v-else-if="!visible.length" class="workspace-empty"><BookOpen :size="40"/><h2>{{search?'没有找到作品':mode==='recent'?'这里还没有最近的故事':mode==='bookmarks'?'尚未收藏私人小说':'开始你的第一个故事'}}</h2><p>{{search?'换一个关键词，或清除筛选。':mode==='bookmarks'?'在小说书架点击星标收藏，章节书签在阅读器中管理。':'可以从蓝宝石案开始，也可以导入一部自己的小说。'}}</p><button v-if="search||kind" @click="search='';kind=''">清除筛选</button><RouterLink v-else :to="mode==='bookmarks'?'/library':'/explore'" class="inline-link">{{mode==='bookmarks'?'前往小说书库':'探索精选故事'}}</RouterLink></section><div v-else class="workspace-collection" :class="{'workspace-collection-list':layout==='list'}"><article v-for="item in visible" :key="item.kind+item.id" class="workspace-work-card"><RouterLink :to="item.path" class="workspace-work-art" :class="{'cover-blue':item.kind==='world','has-curated-art':item.kind==='world'&&artworkWorlds.has(item.id)}"><CuratedCover v-if="item.kind==='world'&&artworkWorlds.has(item.id)" :cover-key="artworkWorlds.get(item.id)" :title="item.title"/><template v-else><Compass v-if="item.kind==='world'" :size="45"/><BookOpen v-else :size="45"/><span>{{item.kind==='world'?'互动世界':'私人小说'}}</span></template></RouterLink><div class="workspace-work-copy"><div class="row between"><small>{{item.subtitle}}</small><button class="icon-button" :aria-label="'管理'+item.title" @click="manage(item)"><MoreHorizontal :size="20"/></button></div><h2><RouterLink :to="item.path">{{item.title}}</RouterLink></h2><p>{{item.description}}</p><div class="workspace-work-footer"><span>{{item.status==='archived'?'已归档':item.kind==='world'?'私人世界':'账号小说'}}</span><RouterLink :to="item.path" class="inline-link">{{mode==='recent'?'继续体验':'进入作品'}}</RouterLink></div></div></article></div><section v-if="favorites" style="margin-top:28px"><h2>收藏的公开作品</h2><PublicCatalog :favorites="true"/></section><p class="workspace-footnote">这里保存当前账号的私人内容；已发布作品可在<RouterLink to="/explore">作品探索</RouterLink>中浏览。</p><Sheet v-if="selected" title="管理作品" @close="!busy&&(selected=undefined)"><p v-if="error" class="error" role="alert">{{error}}</p><label>作品名称<input v-model="name" :maxlength="selected.kind==='world'?160:200" :disabled="busy"></label><button class="primary" :disabled="busy||!name.trim()" @click="save()">{{busy?'正在保存…':'保存名称'}}</button><div class="divider"><RouterLink v-if="selected.kind==='world'" :to="'/worlds/'+selected.id+'/author'" class="inline-link">作者配置与公开发布</RouterLink><button :disabled="busy" @click="save(selected.status==='archived'?'active':'archived')"><RotateCcw v-if="selected.status==='archived'" :size="18"/><Archive v-else :size="18"/>{{selected.status==='archived'?'恢复作品':'归档作品'}}</button><RouterLink :to="selected.kind==='world'?'/worlds':'/library'" class="inline-link">更多管理操作</RouterLink></div></Sheet></div></template>
